sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    // 1. Capturar o "pacote" de dados (JSON) enviado
    var body = request.body.data;

    // 2. Preparar o ServiceNow para criar um novo registro na tabela 'incident'
    var grIncident = new GlideRecord('incident');
    grIncident.initialize(); // Inicia um registro em branco

    // 3. Preencher os campos do incidente com os dados exatos do teu JSON
    grIncident.short_description = body.short_description;
    grIncident.description = body.description;
    grIncident.contact_type = 'integration'; // Define a origem do chamado

    // 4. Salvar o registro no banco de dados e guardar o ID gerado
    var incidentId = grIncident.insert();

    // 5. Montar a resposta que o ServiceNow vai devolver para o sistema externo
    response.setStatus(201); // 201 é o código HTTP para "Registro Criado"

    // Devolvemos um JSON de confirmação com o número do chamado gerado
    response.setBody({
        "status": "sucesso",
        "mensagem": "Incidente gerado via Webhook",
        "numero_incidente": grIncident.getValue('number'),
        "id_registro": incidentId
    });

})(request, response);
